CREATE FUNCTION public.master_plan_guard_identity_links() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF current_user IN('anon','authenticated') THEN IF TG_OP='INSERT' THEN IF NEW.user_id IS NOT NULL THEN RAISE EXCEPTION 'identity_link_requires_verified_bootstrap'; END IF; IF TG_TABLE_NAME='profiles' AND NEW.collaborator_id IS NOT NULL THEN RAISE EXCEPTION 'identity_link_requires_verified_bootstrap'; END IF; ELSIF NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'identity_link_requires_verified_bootstrap'; ELSIF TG_TABLE_NAME='profiles' AND NEW.collaborator_id IS DISTINCT FROM OLD.collaborator_id THEN RAISE EXCEPTION 'identity_link_requires_verified_bootstrap'; ELSIF TG_TABLE_NAME='collaborators' AND OLD.user_id IS NOT NULL AND (NEW.email IS DISTINCT FROM OLD.email OR NEW.is_active IS DISTINCT FROM OLD.is_active) THEN RAISE EXCEPTION 'linked_identity_requires_administration'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER master_plan_collaborator_identity_guard BEFORE INSERT OR UPDATE ON public.collaborators FOR EACH ROW EXECUTE FUNCTION public.master_plan_guard_identity_links();
CREATE TRIGGER master_plan_profile_identity_guard BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.master_plan_guard_identity_links();
REVOKE ALL ON FUNCTION public.master_plan_guard_identity_links() FROM PUBLIC,anon,authenticated;